steps.script:
var main = tree.root.get_node("Main")
TerrainManager.set_meta("tac_saved_layout", TerrainManager.current_layout)
TerrainManager.load_terrain_layout("take_and_hold_vs_reconnaissance_1")
var units = GameState.state["units"]
var px = 40.0
var keep = {"U_TELEMON_HEAVY_DREADNOUGHT_I": [Vector2(32.0, 57.5)], "U_BOYZ_K": []}
for uid in units:
	if not keep.has(uid):
		for m in units[uid].get("models", []):
			m["alive"] = false
		continue
	units[uid]["flags"] = {}
	units[uid]["status"] = GameStateData.UnitStatus.DEPLOYED
var tel = units["U_TELEMON_HEAVY_DREADNOUGHT_I"]["models"][0]
tel["position"] = {"x": 32.0 * px, "y": 57.5 * px}
tel["rotation"] = 0.0
var k = 0
for m in units["U_BOYZ_K"]["models"]:
	if m.get("alive", true):
		m["position"] = {"x": (6.0 + (k % 5) * 1.4) * px, "y": (6.0 + int(k / 5) * 1.4) * px}
		k += 1
PhaseManager.get_current_phase_instance().update_local_state(GameState.create_snapshot())
main._recreate_unit_visuals()
main.movement_controller._refresh_unit_list()
return "ok"

var ph = PhaseManager.get_current_phase_instance()
var a = Vector2(32.0, 57.5) * 40.0
var b = Vector2(32.0, 52.5) * 40.0
var climb = float(ph._get_vertical_climb_cost(a, b, "U_TELEMON_HEAVY_DREADNOUGHT_I"))
var pen = float(ph._get_movement_terrain_penalty(a, b, "U_TELEMON_HEAVY_DREADNOUGHT_I", false))
var chg = float(TerrainManager.calculate_charge_terrain_penalty(a, b, false, ["VEHICLE", "WALKER"]))
var dest_piece = str(TerrainManager.get_terrain_at_position(b).get("id", ""))
print("[%s] 5in move into area-large-7 open ground: dest=%s climb=%.1f move_penalty=%.1f charge_penalty=%.1f" % ["vehicle_enters_area_open_ground_11e", dest_piece, climb, pen, chg])
return "%s|%.1f|%.1f|%.1f" % [dest_piece, climb, pen, chg]

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_log_file_path(), FileAccess.READ)
if f == null:
	return -1
var n = 0
var bad = []
while not f.eof_reached():
	var l = f.get_line()
	if l.contains("[ERROR"):
		n += 1
		bad.append(l)
print("[vehicle_enters_area_open_ground_11e log] ERROR lines = ", n, " ", bad.slice(0, 3))
return n

if TerrainManager.has_meta("tac_saved_layout"):
	var lay = str(TerrainManager.get_meta("tac_saved_layout"))
	TerrainManager.remove_meta("tac_saved_layout")
	if lay != "":
		TerrainManager.load_terrain_layout(lay)
return true
